ee:variables.ee:set-variable:
%dw 2.0
output application/java
var nombreCabecera = lower(p('poc.trazabilidad.cabeceraCorrelacion') default "x-correlation-id")
var cabeceras = (vars.cabecerasEntrada default {}) as Object
var desdeCabecera = (cabeceras filterObject ((valor, clave) -> lower(clave as String) == nombreCabecera) pluck $)[0]
// Algunos orígenes (p. ej. el tool-listener MCP) usan como correlationId el id JSON-RPC ("n:2"), que no es
// único entre sesiones: en ese caso se genera un UUID.
var desdeMule = if (sizeOf((correlationId default "") as String) >= 16) correlationId else uuid()
---
((desdeCabecera default vars.correlationIdEntrante) default desdeMule) as String

%dw 2.0
output application/java
import try from dw::Runtime
var niveles = {TRACE: 0, DEBUG: 10, INFO: 20, WARN: 30, ERROR: 40}
var evt = vars.logEvt default {}
var nivel = upper(evt.nivel default "INFO")
var umbral = upper(p('poc.logging.nivel') default "INFO")
var emitir = (niveles[nivel] default 20) >= (niveles[umbral] default 20)
var camposSensibles = ((p('poc.logging.camposSensibles') default "") splitBy ",") map trim($)
var enmascarar = (p('poc.logging.enmascararDatos') default "false") == "true"
var incluirDatos = (p('poc.logging.incluirDatos') default "true") == "true"
var maxChars = (p('poc.logging.maxCaracteresDatos') default "4000") as Number
var ahora = now() as Number {unit: "milliseconds"}
// Claves que NUNCA se escriben en el log, esté o no activado el enmascarado de datos personales
var clavesSecretas = ["authorization", "proxy-authorization", "x-api-key"]
fun sinSecretos(v) = v match {
    case o is Object -> o mapObject ((valor, clave) -> {
        (clave): if (clavesSecretas contains lower(clave as String)) "****" else sinSecretos(valor)
    })
    case a is Array -> a map sinSecretos($)
    else -> v
}
fun ocultar(v) = v match {
    case o is Object -> o mapObject ((valor, clave) -> {
        (clave): if (camposSensibles contains (clave as String)) "****" else ocultar(valor)
    })
    case a is Array -> a map ocultar($)
    else -> v
}
fun normalizar(d) = do {
    var datos = sinSecretos(if (enmascarar) ocultar(d) else d)
    var serializado = try(() -> write(datos, "application/json", {indent: false}) as String)
    var texto = if (serializado.success) serializado.result else ("[datos no serializables a JSON: " ++ typeOf(d) as String ++ "]")
    ---
    if (!serializado.success) texto
    else if (sizeOf(texto) > maxChars) (texto[0 to maxChars - 1] ++ "...[truncado, $(sizeOf(texto)) caracteres]")
    else datos
}
var duracion = if (evt.duracionMs != null) evt.duracionMs
               else if ((evt.fase default "") == "RESPUESTA" and vars.tLlamada != null) (ahora - vars.tLlamada)
               else null
---
{
    emitir: emitir,
    nivel: nivel,
    linea: if (!emitir) "" else write({
        ts: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"},
        nivel: nivel,
        entorno: p('poc.entorno'),
        dominio: vars.segmento.dominio default "n/a",
        segmento: vars.segmento.nombre default "n/a",
        flujo: evt.flujo default "n/a",
        paso: evt.paso,
        fase: evt.fase,
        mensaje: evt.mensaje,
        correlationId: vars.correlationId default correlationId,
        (a2a: vars.a2aCtx) if (vars.a2aCtx != null),
        (duracionMs: duracion) if (duracion != null),
        (msDesdeInicioFlujo: ahora - vars.tInicioFlujo) if (vars.tInicioFlujo != null),
        (datos: normalizar(evt.datos)) if (incluirDatos and evt.datos != null)
    }, "application/json", {indent: false}) as String
}

%dw 2.0
output application/java
var nombreCabecera = lower(p('poc.seguridad.cabecera') default "x-api-key")
var cabeceras = (vars.cabecerasEntrada default {}) as Object
var presentada = (cabeceras filterObject ((v, k) -> lower(k as String) == nombreCabecera) pluck $)[0]
var esperada = p('poc.seguridad.apiKey')
var configurada = (esperada != null) and (trim(esperada as String) != "")
---
{
    configurada: configurada,
    valido: configurada and (presentada != null) and ((presentada as String) == (esperada as String)),
    motivo: if (not configurada) "El servidor no tiene configurada la API key (propiedad poc.seguridad.apiKey)"
            else if ((presentada default "") == "") "Falta la cabecera X-API-Key"
            else if ((presentada as String) != (esperada as String)) "API key no válida"
            else "OK"
}
